UPDATE scholarships SET title = 'NTU International Outstanding Graduate Student Scholarship', coverage_type = 'Tuition Waiver + Stipend', amount_usd_value = 0, deadline = 'In-study award with an annual spring window: the 2026 application ran 23 April to 15 May 2026 and is closed; applications and renewals take place each April-May through the International Degree Current Student System, with exact dates announced per round on the Office of International Affairs pages.', degree_levels = '["Master''s","PhD"]', eligible_majors = '["All Majors"]', min_gpa = NULL, min_ielts = NULL, merit_based = true, description = 'National Taiwan University''s merit award for international graduate students who are already enrolled at NTU. It is an in-study scholarship, not an admission-stage award: applicants must be current international master''s students within their first two years or doctoral students within their first four years at NTU. The award combines a tuition waiver of up to NTD 100,000 with a monthly stipend that is provided by the student''s advisor or department and may come with corresponding responsibilities as assigned: NTD 8,000 per month for master''s students in every college, and for doctoral students NTD 10,000 per month in the Colleges of Liberal Arts, Law, Social Sciences and Management and NTD 15,000 per month in other colleges. Administrative fees, thesis advisor''s fees, insurance, accommodation, internet and credit fees are expressly excluded and remain the recipient''s own cost, so the award tops up an NTU degree rather than fully funding it from outside. Support runs to the end of the second year for a master''s and the fourth year for a doctorate, subject to the annual April-May renewal review, and lapses on graduation, leave of absence or withdrawal. A student from Uzbekistan can compete for it on the same terms as any other international student once enrolled at NTU, but should not plan admission itself around this award: NTU states that Taiwan Scholarship awardees should not apply for NTU scholarships, and first-year costs need their own funding plan (NTU''s admission-stage scholarships are a separate family, applied for through the degree application).', requirements = 'Be a current international graduate student at National Taiwan University (this award cannot be applied for from outside NTU or before enrolment): master''s students up to the 2nd year, doctoral students up to the 4th year. Apply in the annual window (the 2026 round ran 23 April-15 May 2026; renewals each April-May) through the International Degree Current Student System with: past-years transcripts or the Advisor Evaluation Form, a recommendation letter on the dedicated form for this scholarship, a curriculum vitae, and any other supporting materials. The monthly stipend is provided by the advisor or the department and may carry assigned responsibilities. After selection, upload the Alien Resident Certificate and the postal bank account passbook cover to the same system. Continuation is by annual renewal application each April-May, and the scholarship becomes invalid on graduation, leave of absence or withdrawal. NTU states that Taiwan Scholarship awardees should not apply for NTU scholarships, so do not plan to stack this award on top of a Taiwan government scholarship.', website_url = 'https://isss.ntu.edu.tw/finances/scholarships/', eligible_countries = '["All"]', funding_type = 'University in-study merit award: tuition waiver up to NTD 100,000 plus an advisor/department-funded monthly stipend', tuition_coverage = 'Tuition waiver of up to NTD 100,000 (the Office of International Affairs page does not state whether the cap applies per semester or per year; confirm on the current round notice). The waiver excludes administrative fees, thesis advisor''s fees, insurance, accommodation, internet service and credit fees, which the recipient pays. The monthly stipend (NTD 8,000 master''s; NTD 10,000 or 15,000 doctoral by college group) is paid by the advisor or department and may come with assigned responsibilities.', living_allowance = NULL, travel_allowance = NULL, accommodation = NULL, application_fee = NULL, english_requirements = 'No scholarship-level English score is published for this award: it is granted to students already enrolled in NTU graduate programmes, so the language requirement is the one set by the admitted programme (English- or Chinese-taught).', required_documents = '["Past-years transcripts or Advisor Evaluation Form","Recommendation letter for the Outstanding International Graduate Student Scholarship (dedicated form)","Curriculum vitae","Other supporting materials (optional)"]', application_url = 'https://oiasystem.ntu.edu.tw/ntu_oia_int_student/student/auth?lang=en', opening_date = NULL, deadline_date = NULL, deadline_type = 'not_published', deadline_range_start = NULL, deadline_range_end = NULL, rounds = '[{"round":"2026","application":"2026-04-23 to 2026-05-15","status":"closed"},{"pattern":"Annual: applications and renewals each April-May via the International Degree Current Student System, exact dates announced per round"}]', recurrence = 'annual', expected_opening_period = 'April each year', expected_deadline_period = 'Mid-May each year (2026 round closed 15 May 2026)', application_status = 'upcoming', last_verified_at = '2026-10-29 15:00:00+05', last_updated_at = '2026-10-29 15:00:00+05', verification_status = 'verified', source_reliability = 10, source_url = 'https://isss.ntu.edu.tw/finances/scholarships/', notes = 'REWRITTEN in Pass 126 on 2026-10-29 from reliability 4 to 10 after the terms were finally read first-hand. Provenance: the 2026-10-26 decontamination had stripped an invented USD 20,000 and a "20 February annually" deadline and left a placeholder because the OIA site answered "under maintenance". On 2026-10-29 the OIA CMS deep links still redirect to the OIA homepage in this environment, but NTU''s WordPress surfaces were readable: the International Student Support Service scholarships page (source 3148) carries this award''s full current terms (eligibility - current international graduate students, master''s up to 2nd year and PhD up to 4th; tuition waiver up to NTD 100,000 with the fee exclusions; advisor/department-paid stipend table NTD 8,000 / 10,000 / 15,000 by level and college group, possibly with duties; documents; 2026 window 23 April-15 May 2026; duration and invalidity rules; April-May renewal), corroborated by the admissions scholarships page (source 3149) for the NTU scholarship ecosystem and the rule that Taiwan Scholarship awardees should not apply for NTU scholarships. The stored title had the official name transposed ("Outstanding International Graduate" for "International Outstanding Graduate Student"); the title is corrected to the official name and the record remains the same award. Two deliberate non-encodings: the fetched page does not state whether the NTD 100,000 waiver cap is per semester or per year (flagged in tuition_coverage), and older structures of this award visible only in search-index snippets of an OIA steps page (different stipends for 2020/2021 and 2021/2022) were NOT used - only today''s fetched terms are recorded. No GPA or IELTS minimum is published for this award itself (the 3.38 standards on NTU pages belong to other schemes), so minima stay NULL. The university_scholarships row at National Taiwan University (university 64, row 660) was renamed to the official title and re-synced (it previously claimed "Fully Funded").', is_active = true, university_id = 64, award_amount = NULL, award_currency = 'TWD', award_period = 'month', award_basis = 'variable' WHERE id = 342;

UPDATE university_scholarships SET scholarship_name = 'NTU International Outstanding Graduate Student Scholarship', availability_status = 'available', funding_type = 'Tuition waiver + departmental stipend (current students)', max_scholarship = 'Tuition waiver up to NTD 100,000 plus NTD 8,000/month (master''s) or NTD 10,000-15,000/month (PhD) stipend from the advisor/department', valued_aspect = 'Academic merit (advisor recommendation)', eligibility_notes = 'For international graduate students already enrolled at NTU: master''s within the 2nd year, PhD within the 4th year. Applied for each April-May via the International Degree Current Student System; not an admission-stage award and not stackable with Taiwan government scholarships.', official_url = 'https://isss.ntu.edu.tw/finances/scholarships/', source_url = 'https://isss.ntu.edu.tw/finances/scholarships/', last_verified_at = '2026-10-29 15:00:00+05' WHERE id = 660;

-- 3) Retire 502 (invented Chula award name)
UPDATE scholarships SET title = 'Chulalongkorn University "International Excellence Scholarship" (retired — no such award; the real route for international postgraduates is the Chula LINK Scholarship)', coverage_type = 'Unspecified', amount_usd_value = 0, deadline = 'No such award exists — do not apply. International master''s and doctoral students at Chulalongkorn are funded through the Chula LINK Scholarship (separate catalogue record) on top of an existing admission; Thailand''s government channel is the Thailand International Postgraduate Programme (TIPP), also catalogued separately', degree_levels = '["Master''s","PhD"]', eligible_majors = '["All Majors"]', min_gpa = NULL, min_ielts = NULL, merit_based = true, description = 'This record is retired because Chulalongkorn University publishes no "International Excellence Scholarship". The university''s own scholarships catalogue page, read in full on 2026-10-29, divides its funding into internal university awards and external support, and the internal list is built for Chula''s own enrolled students rather than for international applicants: undergraduate grant-in-aid (tuition, monthly expenses and other assistance for students lacking funds), the Bhumibol scholarship for undergraduates with excellent grades or good grades and financial need, awarded through faculty nomination, awards for students who build the university''s reputation in sport, arts, culture or social activities, the Chula Rural scholarship for students domiciled in rural areas, student welfare relief for disasters and emergencies, graduate-study grants administered through the Graduate School (including the 100th-anniversary doctoral scholarship), and graduate research grants (including the 90th-anniversary fund, thesis support and research or conference travel at home and abroad). The external side is the national student-loan fund, donor-funded undergraduate aid for good students in financial need, and ministry support for students with disabilities. None of this is an excellence flagship an international applicant can apply for alongside admission, and dressing the internal grant catalogue up as one would misstate who the money is for. The genuine Chulalongkorn channel for a student from Uzbekistan is the Chula LINK Scholarship (Chulalongkorn Leaders in International Networks and Knowledge), catalogued separately in this database: it is for international students who do not hold a Thai passport, admitted to or in the first semester of a master''s or doctoral programme, and is run through the Office of International Affairs and Global Network. Thailand''s government postgraduate channel, the Thailand International Postgraduate Programme (TIPP), is likewise a separate record. The imported name is therefore withdrawn rather than rewritten.', requirements = 'Do not apply for a Chulalongkorn "International Excellence Scholarship" — none exists, and Chulalongkorn runs no general scholarship for international undergraduates. For funded postgraduate study at Chula: first secure admission to a master''s or doctoral programme, then apply for the Chula LINK Scholarship (see the separate catalogue record for its round, eligibility and coverage) as an admitted or first-semester international student without a Thai passport; separately, Thailand''s Thailand International Postgraduate Programme (TIPP) funds postgraduate study through government nomination (also a separate record). Chula''s internal grant catalogue (undergraduate grant-in-aid, the Bhumibol prize, rural and welfare funds, and Graduate School study and research grants) serves its enrolled, largely domestic student body and is not an application route for a prospective international student.', website_url = 'https://www.chula.ac.th/academics/admissions/scholarships/', eligible_countries = '["All"]', funding_type = 'Retired: imported name; Chulalongkorn publishes no such scholarship (real channels: Chula LINK Scholarship, record 555; TIPP, record 934)', tuition_coverage = 'No international excellence award exists to describe. Chulalongkorn''s published scholarship catalogue covers internal awards for its own students (undergraduate grant-in-aid and prizes, rural and welfare support, Graduate School study and research grants) and external loans and donor aid; it contains no tuition offer for prospective international students. Tuition support for international postgraduates runs through the separately catalogued Chula LINK Scholarship.', living_allowance = NULL, travel_allowance = NULL, accommodation = NULL, application_fee = NULL, english_requirements = 'Not applicable to a nonexistent award; the English requirement is the one set by the admitted Chulalongkorn programme (and by the Chula LINK Scholarship round, where relevant).', required_documents = '[]', application_url = 'https://www.chula.ac.th/academics/admissions/scholarships/', opening_date = NULL, deadline_date = NULL, deadline_type = 'not_published', deadline_range_start = NULL, deadline_range_end = NULL, rounds = '[]', recurrence = 'annual', expected_opening_period = NULL, expected_deadline_period = NULL, application_status = 'closed', last_verified_at = '2026-10-29 15:00:00+05', last_updated_at = '2026-10-29 15:00:00+05', verification_status = 'verified', source_reliability = 9, source_url = 'https://www.chula.ac.th/academics/admissions/scholarships/', notes = 'RETIRED in Pass 126 on 2026-10-29 as an invented (imported) award name. Provenance: the 2026-10-26 decontamination had already stripped an invented USD 6,500 from this row and left it at reliability 4 because the university page could not be read then. On 2026-10-29 two official Chulalongkorn pages (in Thai; the stored English URL now redirects into the Thai site) were read in full: the admissions hub (source 3151) and the university''s scholarships catalogue page (source 3150). The catalogue lists internal awards for enrolled students (undergraduate grant-in-aid for those lacking funds; the Bhumibol undergraduate prize by faculty nomination; reputation/community-benefit awards; the Chula Rural scholarship for rural-domicile students; student welfare relief; Graduate School graduate-study grants including the 100th-anniversary doctoral scholarship; graduate research grants including the 90th-anniversary fund and thesis/conference support; a media scholarship for journalists) plus external support (the national student-loan fund, donor undergraduate aid, ministry disability support) - and no award for prospective international students under this or any similar name. The real international route is already catalogued: the Chula LINK Scholarship (record 555, reliability 8), which its own record notes is the award a student from Uzbekistan can actually win, alongside the government Thailand International Postgraduate Programme (record 934, reliability 10). Degree levels narrowed to master''s/PhD to match the real channels the name mimicked. The university_scholarships row carrying the invented name at Chulalongkorn University (university 189, row 663) was deleted with this retirement. Retain inactive; do not revive under this name.', is_active = false, university_id = 189, award_amount = NULL, award_currency = NULL, award_period = NULL, award_basis = NULL WHERE id = 502;

